package com.xlox.ui;

import android.view.View;
import android.view.animation.LinearInterpolator;

import com.airbnb.lottie.LottieAnimationView;
import com.airbnb.lottie.LottieDrawable;
import com.airbnb.lottie.LottieProperty;
import com.airbnb.lottie.model.KeyPath;
import com.airbnb.lottie.value.LottieValueCallback;
import com.xlox.R;

/**
 * 2.3.7: the quiet status Lotties (res/raw, generated by scripts/lottie_art.py).
 *
 *   arc    anoy_arc    2.4 s loop - waiting (splash, home "Preparing", library sheet)
 *   check  anoy_check  0.7 s one-shot, then holds - done
 *   draw   anoy_key    0.8 s one-shot, then holds - login mark
 *
 * Reduced motion (animator scale 0): no movement - the arc is one still
 * frame, one-shots show their last frame. Calling the same state again does
 * not restart it, so status refreshes never make it flicker.
 */
public final class Motion {

    private Motion() {
    }

    /** Still frame of the arc under reduced motion. */
    private static final float ARC_STILL = 0f;

    /** Quiet loop while something is in progress. */
    public static void arc(LottieAnimationView view) {
        show(view, R.raw.anoy_arc, true);
    }

    /** One-shot check that draws in and holds. */
    public static void check(LottieAnimationView view) {
        show(view, R.raw.anoy_check, false);
    }

    /** One-shot draw-on that then stays static (login key). */
    public static void drawOnce(LottieAnimationView view, int rawRes) {
        show(view, rawRes, false);
    }

    /**
     * Arc -> check as one motion: the arc fades out (100 ms), the check draws
     * in while fading back (180 ms). Instant under reduced motion or when
     * nothing was showing.
     */
    public static void arcToCheck(LottieAnimationView view) {
        if (view == null) return;
        boolean showingArc = view.getVisibility() == View.VISIBLE
                && Integer.valueOf(R.raw.anoy_arc).equals(view.getTag(R.id.tag_lottie_res));
        view.animate().cancel();
        if (!showingArc || Ui.reducedMotion(view.getContext())) {
            view.setAlpha(1f);
            check(view);
            return;
        }
        view.animate().alpha(0f).setDuration(Ui.SWAP_OUT).setInterpolator(new LinearInterpolator())
                .withEndAction(() -> {
                    check(view);
                    view.animate().alpha(1f).setDuration(Ui.SWAP_IN)
                            .setInterpolator(new LinearInterpolator()).start();
                }).start();
    }

    /** Stops and removes it (GONE) at once. */
    public static void hide(LottieAnimationView view) {
        if (view == null) return;
        view.animate().cancel();
        view.cancelAnimation();
        view.setAlpha(1f);
        view.setVisibility(View.GONE);
        view.setTag(R.id.tag_lottie_res, null);
    }

    /**
     * Keeps the stroke at {@code dp} whatever size the view is drawn at (the
     * files are 1.75 dp at their design size). Set once per view.
     */
    public static void stroke(LottieAnimationView view, float dp) {
        if (view == null || view.getTag(R.id.tag_lottie_stroke) != null) return;
        view.setTag(R.id.tag_lottie_stroke, dp);
        view.addLottieOnCompositionLoadedListener(composition -> {
            float density = view.getResources().getDisplayMetrics().density;
            int widthPx = view.getLayoutParams() != null ? view.getLayoutParams().width : 0;
            if (widthPx <= 0 || composition.getBounds().width() <= 0) return;
            // Units per dp: the composition's design width over the view's width.
            float units = dp * (composition.getBounds().width() / density) / (widthPx / density);
            view.addValueCallback(new KeyPath("**"), LottieProperty.STROKE_WIDTH,
                    new LottieValueCallback<>(units));
        });
    }

    private static void show(LottieAnimationView view, int rawRes, boolean loop) {
        if (view == null) return;
        boolean reduced = Ui.reducedMotion(view.getContext());
        boolean same = Integer.valueOf(rawRes).equals(view.getTag(R.id.tag_lottie_res));
        if (view.getVisibility() != View.VISIBLE) {
            // Arrives with its line: a 180 ms fade, like the text beside it.
            view.setVisibility(View.VISIBLE);
            if (!reduced) {
                view.setAlpha(0f);
                view.animate().alpha(1f).setDuration(Ui.SWAP_IN).setInterpolator(new LinearInterpolator()).start();
            }
        }
        if (same && (!loop || reduced || view.isAnimating())) return;
        view.setTag(R.id.tag_lottie_res, rawRes);
        view.cancelAnimation();
        view.setAnimation(rawRes);
        view.setRepeatCount(loop ? LottieDrawable.INFINITE : 0);
        if (reduced) {
            view.setProgress(loop ? ARC_STILL : 1f);
        } else {
            view.setProgress(0f);
            view.playAnimation();
        }
    }
}
